            v = random.randint(0, n - 1)
            if u == v or graph[u][v] == 1:
                continue
            graph[u][v] = 1
            graph[v][u] = 1
            degree_count[u] += 1
            degree_count[v] += 1

        return graph

    def matrix_multiplication(A: list, B: list) -> list:
        n = len(A)
        C = [[0] * n for _ in range(n)]
        for i in range(n):
            for j in range(n):
                for k in range(n):
                    C[i][j] += A[i][k] * B[k][j]
        return C

    def gaussian_elimination(A: list) -> int:
        n = len(A)
        rank = 0
        for i in range(n):
            if A[i][i] == 0:
                for j in range(i + 1, n):
                    if A[j][i] != 0:
                        A[i], A[j] = A[j], A[i]
                        break
                else:
                    continue
            pivot = A[i][i]
            for j in range(n):
                A[i][j] /= pivot
            for k in range(n):
                if k != i and A[k][i] != 0:
                    factor = A[k][i]
                    for j in range(n):
                        A[k][j] -= factor * A[i][j]
            rank += 1
        return rank

